module @_QMsafe_sqrt {
  func.func @_QPsafe_sqrt(
      %arg0: !fir.ref<!fir.array<?xf32>> {fir.bindc_name = "result", fir.inout},
      %arg1: !fir.ref<!fir.array<?xf32>> {fir.bindc_name = "input", fir.in},
      %arg2: !fir.ref<i32>               {fir.bindc_name = "n", fir.in}
  ) {
    %c0     = arith.constant 0.0 : f32
    %c1     = arith.constant 1 : index
    %n_val  = fir.load %arg2 : !fir.ref<i32>
    %n_idx  = fir.convert %n_val : (i32) -> index
    %shape  = fir.shape %n_idx : (index) -> !fir.shape<1>
    %in_arr = fir.array_load %arg1(%shape) : (!fir.ref<!fir.array<?xf32>>, !fir.shape<1>) -> !fir.array<?xf32>
    %res_arr= fir.array_load %arg0(%shape) : (!fir.ref<!fir.array<?xf32>>, !fir.shape<1>) -> !fir.array<?xf32>

    // The WHERE condition materializes as an fir.do_loop with fir.if branching
    %result = fir.do_loop %iv = %c1 to %n_idx step %c1
                  iter_args(%acc = %res_arr) -> (!fir.array<?xf32>) {
      %in_el  = fir.array_fetch %in_arr, %iv : (!fir.array<?xf32>, index) -> f32
      %zero   = arith.constant 0.0 : f32
      %mask   = arith.cmpf ogt, %in_el, %zero : f32   // input(iv) > 0.0

      // fir.if encodes the WHERE / ELSEWHERE split
      %upd = fir.if %mask -> (!fir.array<?xf32>) {
        // WHERE body: result(iv) = SQRT(input(iv))
        %sq   = math.sqrt %in_el : f32               // SQRT intrinsic → llvm.sqrt
        %a2   = fir.array_update %acc, %sq, %iv : (!fir.array<?xf32>, f32, index) -> !fir.array<?xf32>
        fir.result %a2 : !fir.array<?xf32>
      } else {
        // ELSEWHERE body: result(iv) = 0.0
        %a3   = fir.array_update %acc, %c0, %iv : (!fir.array<?xf32>, f32, index) -> !fir.array<?xf32>
        fir.result %a3 : !fir.array<?xf32>
      }
      fir.result %upd : !fir.array<?xf32>
    }
    fir.array_merge_store %res_arr, %result to %arg0
        : !fir.array<?xf32>, !fir.array<?xf32>, !fir.ref<!fir.array<?xf32>>
    return
  }
} loc(#loc1)
