// *** IR Dump After HLFIR Lowering (flang-lower-hlfir) ***
module @_QMsafe_sqrt {
  func.func @_QPsafe_sqrt(
      %arg0: !fir.ref<!fir.array<?xf32>> {fir.bindc_name = "result", fir.inout},
      %arg1: !fir.ref<!fir.array<?xf32>> {fir.bindc_name = "input",  fir.in},
      %arg2: !fir.ref<i32>               {fir.bindc_name = "n",      fir.in}
  ) {
    %0 = fir.load %arg2 : !fir.ref<i32>
    %1 = fir.convert %0 : (i32) -> index
    %shape = fir.shape %1 : (index) -> !fir.shape<1>

    %result:2 = hlfir.declare %arg0(%shape)
        {fortran_attrs = #fir.var_attrs<intent_out>, uniq_name = "_QFsafe_sqrtEresult"}
        : (!fir.ref<!fir.array<?xf32>>, !fir.shape<1>)
       -> (!fir.box<!fir.array<?xf32>>, !fir.ref<!fir.array<?xf32>>)

    %input:2 = hlfir.declare %arg1(%shape)
        {fortran_attrs = #fir.var_attrs<intent_in>, uniq_name = "_QFsafe_sqrtEinput"}
        : (!fir.ref<!fir.array<?xf32>>, !fir.shape<1>)
       -> (!fir.box<!fir.array<?xf32>>, !fir.ref<!fir.array<?xf32>>)

    // WHERE mask evaluated as hlfir.elemental producing !hlfir.expr<?x!fir.logical<4>>
    %mask_expr = hlfir.elemental %shape
        : (!fir.shape<1>) -> !hlfir.expr<?x!fir.logical<4>> {
    ^bb0(%i: index):
      %in_el = hlfir.apply %input#0, %i : (!fir.box<!fir.array<?xf32>>, index) -> f32
      %zero  = arith.constant 0.0 : f32
      %cmp   = arith.cmpf ogt, %in_el, %zero : f32
      %log   = fir.convert %cmp : (i1) -> !fir.logical<4>
      hlfir.yield_element %log : !fir.logical<4>
    }

    // WHERE body: SQRT(input) applied only where mask is .TRUE.
    %sqrt_expr = hlfir.elemental %shape
        : (!fir.shape<1>) -> !hlfir.expr<?xf32> {
    ^bb0(%i: index):
      %mask_el = hlfir.apply %mask_expr, %i : (!hlfir.expr<?x!fir.logical<4>>, index) -> !fir.logical<4>
      %in_el   = hlfir.apply %input#0, %i   : (!fir.box<!fir.array<?xf32>>, index) -> f32
      %sq      = math.sqrt %in_el : f32
      %zero    = arith.constant 0.0 : f32
      %mask_i1 = fir.convert %mask_el : (!fir.logical<4>) -> i1
      %sel     = arith.select %mask_i1, %sq, %zero : f32   // WHERE/ELSEWHERE merge
      hlfir.yield_element %sel : f32
    }

    hlfir.assign %sqrt_expr to %result#0
        : !hlfir.expr<?xf32>, !fir.box<!fir.array<?xf32>>
    hlfir.destroy %sqrt_expr  : !hlfir.expr<?xf32>
    hlfir.destroy %mask_expr  : !hlfir.expr<?x!fir.logical<4>>
    return
  }
}
